do $$ declare c public.companies; token timestamptz; begin
 select * into strict c from public.companies where id='77000000-0000-4000-8000-0000000000a1';
 perform pg_temp.assert_true('normalized exact metadata',c.legal_name='Legal  اسم' and c.trn='00123' and c.address=E'A\n  B' and c.notes is null);
 perform pg_temp.assert_true('actor and creation preserved',c.updated_by=auth.uid() and c.created_by=auth.uid() and c.created_at='2000-01-01'::timestamptz);
 token:=c.updated_at;
 update public.companies set notes=notes where id=c.id and updated_at=token returning * into c;
 perform pg_temp.assert_true('strict monotonic future token',c.updated_at>token and c.updated_at>'2099-01-01'::timestamptz);
 perform pg_temp.check_sql('stale exact token',format('update public.companies set notes=''stale'' where id=%L and updated_at=%L',c.id,token),null,0);
 update public.companies set legal_name=chr(65279)||chr(8195),trn=chr(160)||chr(9),address='',notes=null where id=c.id returning * into c;
 perform pg_temp.assert_true('Unicode blanks clear all',c.legal_name is null and c.trn is null and c.address is null and c.notes is null);
 update public.companies set legal_name=repeat('名',10001),trn='AbC-0001',address='  Inside  Text  ',notes=E' \nMiXeD\n  Internal\n ' where id=c.id returning * into c;
 perform pg_temp.assert_true('no invented length or TRN policy',length(c.legal_name)=10001 and c.trn='AbC-0001' and c.address='Inside  Text' and c.notes=E'MiXeD\n  Internal');
end $$;
